theory RSF_Verification
imports Main "Imperative_HOL.Imperative_HOL" "HOL-Library.Word" "HOL-Library.Code_Target_Nat"
begin

section ‹Error and Result Types›

datatype err = 
  InvalidDimension | InvalidLayerCount | TooLarge | NonFinite | InvalidConfig 
  | ShapeMismatch | DataLengthMismatch | NotInitialized | NumericFailure 
  | BadFileFormat | UnsupportedVersion | Overflow | OutOfMemory | IoError

datatype ('a, 'e) result = Ok 'a | Err 'e

fun bind_result :: "('a, 'e) result ⇒ ('a ⇒ ('b, 'e) result) ⇒ ('b, 'e) result" (infixl "⤜" 54) where
"Ok x ⤜ f = f x" |
"Err e ⤜ f = Err e"

definition return_result :: "'a ⇒ ('a, 'e) result" where
"return_result x = Ok x"

definition fail_result :: "'e ⇒ ('a, 'e) result" where
"fail_result e = Err e"

section ‹IEEE-754 F32 Model›

type_synonym f32 = "32 word"

definition f32_exp_mask :: "32 word" where "f32_exp_mask = 0x7F800000"
definition f32_mant_mask :: "32 word" where "f32_mant_mask = 0x007FFFFF"
definition f32_sign_mask :: "32 word" where "f32_sign_mask = 0x80000000"

definition is_finite :: "f32 ⇒ bool" where
"is_finite x ⟷ (x AND f32_exp_mask) ≠ f32_exp_mask"

definition is_nan :: "f32 ⇒ bool" where
"is_nan x ⟷ ((x AND f32_exp_mask) = f32_exp_mask) ∧ ((x AND f32_mant_mask) ≠ 0)"

definition f32_zero :: f32 where "f32_zero = 0"
definition f32_one :: f32 where "f32_one = 0x3F800000"

consts f32_add :: "f32 ⇒ f32 ⇒ f32"
consts f32_sub :: "f32 ⇒ f32 ⇒ f32"
consts f32_mul :: "f32 ⇒ f32 ⇒ f32"
consts f32_div :: "f32 ⇒ f32 ⇒ f32"
consts f32_exp :: "f32 ⇒ f32"
consts f32_sqrt :: "f32 ⇒ f32"
consts f32_lt :: "f32 ⇒ f32 ⇒ bool"
consts f32_gt :: "f32 ⇒ f32 ⇒ bool"
consts f32_of_nat :: "nat ⇒ f32"

definition clamp_finite :: "f32 ⇒ f32" where
"clamp_finite x = (if is_finite x then x else f32_zero)"

definition f32_clip :: "f32 ⇒ f32 ⇒ f32 ⇒ f32" where
"f32_clip mn mx x = (if f32_lt x mn then mn else if f32_gt x mx then mx else x)"

section ‹Pure Tensor Model›

record tensor_pure =
  p_dims :: "nat list"
  p_data :: "f32 list"

definition valid_tensor_pure :: "tensor_pure ⇒ bool" where
"valid_tensor_pure t ⟷ length (p_dims t) = 2 ∧ length (p_data t) = (p_dims t ! 0) * (p_dims t ! 1)"

definition p_rows :: "tensor_pure ⇒ nat" where "p_rows t = p_dims t ! 0"
definition p_cols :: "tensor_pure ⇒ nat" where "p_cols t = p_dims t ! 1"

definition p_idx :: "tensor_pure ⇒ nat ⇒ nat ⇒ nat" where
"p_idx t r c = r * p_cols t + c"

lemma p_idx_bound:
  assumes "valid_tensor_pure t" "r < p_rows t" "c < p_cols t"
  shows "p_idx t r c < length (p_data t)"
using assms unfolding valid_tensor_pure_def p_rows_def p_cols_def p_idx_def
by (metis add_mult_distrib2 mult.commute nat_add_left_cancel_less trans_less_add2)

definition pure_zeros :: "nat list ⇒ (tensor_pure, err) result" where
"pure_zeros ds = (if length ds = 2 then Ok ⦇ p_dims = ds, p_data = replicate (ds!0 * ds!1) f32_zero ⦈ else Err ShapeMismatch)"

definition pure_transpose :: "tensor_pure ⇒ (tensor_pure, err) result" where
"pure_transpose t = (
  if ¬ valid_tensor_pure t then Err ShapeMismatch else
  let r = p_rows t; c = p_cols t; d = p_data t in
  let new_data = concat (map (λj. map (λi. d ! (i * c + j)) [0..<r]) [0..<c]) in
  Ok ⦇ p_dims = [c, r], p_data = new_data ⦈
)"

definition pure_split :: "nat ⇒ tensor_pure ⇒ (tensor_pure × tensor_pure, err) result" where
"pure_split dim t = (
  if ¬ valid_tensor_pure t then Err ShapeMismatch else
  if p_cols t ≠ dim * 2 then Err ShapeMismatch else
  let r = p_rows t in
  let d = p_data t in
  let rows_list = map (λi. take (dim*2) (drop (i*dim*2) d)) [0..<r] in
  let d1 = concat (map (take dim) rows_list) in
  let d2 = concat (map (drop dim) rows_list) in
  Ok (⦇ p_dims = [r, dim], p_data = d1 ⦈, ⦇ p_dims = [r, dim], p_data = d2 ⦈)
)"

definition pure_merge :: "nat ⇒ tensor_pure ⇒ tensor_pure ⇒ (tensor_pure, err) result" where
"pure_merge dim t1 t2 = (
  if ¬ valid_tensor_pure t1 ∨ ¬ valid_tensor_pure t2 then Err ShapeMismatch else
  if p_rows t1 ≠ p_rows t2 ∨ p_cols t1 ≠ dim ∨ p_cols t2 ≠ dim then Err ShapeMismatch else
  let r = p_rows t1 in
  let d1 = p_data t1; d2 = p_data t2 in
  let rows1 = map (λi. take dim (drop (i*dim) d1)) [0..<r] in
  let rows2 = map (λi. take dim (drop (i*dim) d2)) [0..<r] in
  let new_data = concat (map (λ(r1, r2). r1 @ r2) (zip rows1 rows2)) in
  Ok ⦇ p_dims = [r, dim*2], p_data = new_data ⦈
)"

lemma split_merge_correct:
  assumes "valid_tensor_pure t" "p_cols t = dim * 2" "dim > 0"
  assumes "pure_split dim t = Ok (t1, t2)"
  shows "pure_merge dim t1 t2 = Ok t"
proof -
  let ?r = "p_rows t"
  let ?d = "p_data t"
  have len: "length ?d = ?r * (dim * 2)" using assms(1,2) valid_tensor_pure_def p_rows_def p_cols_def by simp
  have t1_def: "t1 = ⦇ p_dims = [?r, dim], p_data = concat (map (take dim) (map (λi. take (dim*2) (drop (i*dim*2) ?d)) [0..<?r])) ⦈"
    using assms(4) pure_split_def assms(1,2) by auto
  have t2_def: "t2 = ⦇ p_dims = [?r, dim], p_data = concat (map (drop dim) (map (λi. take (dim*2) (drop (i*dim*2) ?d)) [0..<?r])) ⦈"
    using assms(4) pure_split_def assms(1,2) by auto

  have valid1: "valid_tensor_pure t1" using t1_def valid_tensor_pure_def len by (simp add: length_concat sum_list_triv)
  have valid2: "valid_tensor_pure t2" using t2_def valid_tensor_pure_def len by (simp add: length_concat sum_list_triv)

  have merge_res: "pure_merge dim t1 t2 = Ok t"
    unfolding pure_merge_def Let_def
    using valid1 valid2 t1_def t2_def assms(1,2) len
    apply (auto simp: p_rows_def p_cols_def)
    apply (rule ext)
    apply (auto)
    done
  show ?thesis using merge_res by simp
qed

section ‹Imperative Layer›

record tensor_impl =
  i_dims :: "nat list"
  i_data :: "f32 array"

definition tensor_valid :: "tensor_impl ⇒ bool heap" where
"tensor_valid t = do {
  len ← Array.len (i_data t);
  return (length (i_dims t) = 2 ∧ len = (i_dims t ! 0) * (i_dims t ! 1))
}"

definition assert2DAndLen :: "tensor_impl ⇒ (unit, err) result heap" where
"assert2DAndLen t = do {
  len ← Array.len (i_data t);
  if length (i_dims t) ≠ 2 then return (Err ShapeMismatch)
  else if len ≠ (i_dims t ! 0) * (i_dims t ! 1) then return (Err DataLengthMismatch)
  else return (Ok ())
}"

definition assertPair :: "nat ⇒ f32 ⇒ f32 ⇒ tensor_impl ⇒ tensor_impl ⇒ tensor_impl ⇒ tensor_impl ⇒ (nat, err) result heap" where
"assertPair dim cmin cmax sb tb a b = do {
  ra ← assert2DAndLen a;
  rb ← assert2DAndLen b;
  case (ra, rb) of
    (Ok _, Ok _) ⇒ do {
       if i_dims a ! 1 ≠ dim ∨ i_dims b ! 1 ≠ dim then return (Err ShapeMismatch)
       else if i_dims a ! 0 ≠ i_dims b ! 0 then return (Err ShapeMismatch)
       else do {
         len_sb ← Array.len (i_data sb);
         len_tb ← Array.len (i_data tb);
         if len_sb ≠ dim ∨ len_tb ≠ dim then return (Err ShapeMismatch)
         else if ¬ is_finite cmin ∨ ¬ is_finite cmax then return (Err NonFinite)
         else if ¬ f32_lt cmin cmax then return (Err InvalidConfig)
         else return (Ok (i_dims a ! 0))
       }
    }
  | (Err e, _) ⇒ return (Err e)
  | (_, Err e) ⇒ return (Err e)
}"

definition clampFiniteInPlace :: "tensor_impl ⇒ unit heap" where
"clampFiniteInPlace t = do {
  len ← Array.len (i_data t);
  let d = i_data t;
  let loop = (λi. do {
      v ← Array.nth d i;
      if ¬ is_finite v then Array.upd i f32_zero d else return ();
      return ()
  });
  mapM loop [0..<len];
  return ()
}"

definition tensor_transpose :: "tensor_impl ⇒ (tensor_impl, err) result heap" where
"tensor_transpose t = do {
  chk ← assert2DAndLen t;
  case chk of Err e ⇒ return (Err e) | Ok _ ⇒ do {
    let r = i_dims t ! 0;
    let c = i_dims t ! 1;
    new_arr ← Array.new (r*c) f32_zero;
    let old_arr = i_data t;
    let loop = (λi. do {
       let loop_inner = (λj. do {
          val ← Array.nth old_arr (i * c + j);
          Array.upd (j * r + i) val new_arr;
          return ()
       });
       mapM loop_inner [0..<c];
       return ()
    });
    mapM loop [0..<r];
    return (Ok ⦇ i_dims = [c, r], i_data = new_arr ⦈)
  }
}"

definition tensor_matmul :: "tensor_impl ⇒ tensor_impl ⇒ (tensor_impl, err) result heap" where
"tensor_matmul a b = do {
  ca ← assert2DAndLen a;
  cb ← assert2DAndLen b;
  case (ca, cb) of (Ok _, Ok _) ⇒ do {
    let m = i_dims a ! 0;
    let k = i_dims a ! 1;
    let k' = i_dims b ! 0;
    let n = i_dims b ! 1;
    if k ≠ k' then return (Err ShapeMismatch) else do {
      res ← Array.new (m*n) f32_zero;
      let da = i_data a;
      let db = i_data b;
      let loop_i = (λi. do {
        let loop_j = (λj. do {
           let loop_k = (λl acc. do {
              v1 ← Array.nth da (i * k + l);
              v2 ← Array.nth db (l * n + j);
              return (f32_add acc (f32_mul v1 v2))
           });
           sum ← foldM loop_k f32_zero [0..<k];
           Array.upd (i * n + j) sum res;
           return ()
        });
        mapM loop_j [0..<n];
        return ()
      });
      mapM loop_i [0..<m];
      return (Ok ⦇ i_dims = [m, n], i_data = res ⦈)
    }
  } | (Err e, _) ⇒ return (Err e) | (_, Err e) ⇒ return (Err e)
}"

definition tensor_add_inplace :: "tensor_impl ⇒ tensor_impl ⇒ (unit, err) result heap" where
"tensor_add_inplace dest src = do {
  cd ← assert2DAndLen dest;
  cs ← assert2DAndLen src;
  case (cd, cs) of (Ok _, Ok _) ⇒ do {
     len ← Array.len (i_data dest);
     len2 ← Array.len (i_data src);
     if len ≠ len2 then return (Err ShapeMismatch) else do {
       let dd = i_data dest;
       let ds = i_data src;
       let loop = (λi. do {
          v1 ← Array.nth dd i;
          v2 ← Array.nth ds i;
          Array.upd i (f32_add v1 v2) dd;
          return ()
       });
       mapM loop [0..<len];
       return (Ok ())
     }
  } | _ ⇒ return (Err ShapeMismatch)
}"

definition tensor_sub_inplace :: "tensor_impl ⇒ tensor_impl ⇒ (unit, err) result heap" where
"tensor_sub_inplace dest src = do {
  cd ← assert2DAndLen dest;
  cs ← assert2DAndLen src;
  case (cd, cs) of (Ok _, Ok _) ⇒ do {
