       let loop = (λi. do {
          v1 ← Array.nth dd i;
          v2 ← Array.nth ds i;
          Array.upd i (f32_sub v1 v2) dd;
          return ()
       });
       mapM loop [0..<len];
       return (Ok ())
     }
  } | _ ⇒ return (Err ShapeMismatch)
}"

definition tensor_mul_inplace :: "tensor_impl ⇒ tensor_impl ⇒ (unit, err) result heap" where
"tensor_mul_inplace dest src = do {
  cd ← assert2DAndLen dest;
  cs ← assert2DAndLen src;
  case (cd, cs) of (Ok _, Ok _) ⇒ do {
     len ← Array.len (i_data dest);
