     }
  } | _ ⇒ return (Err ShapeMismatch)
}"

definition tensor_div_inplace :: "tensor_impl ⇒ tensor_impl ⇒ (unit, err) result heap" where
"tensor_div_inplace dest src = do {
  cd ← assert2DAndLen dest;
  cs ← assert2DAndLen src;
  case (cd, cs) of (Ok _, Ok _) ⇒ do {
     len ← Array.len (i_data dest);
     len2 ← Array.len (i_data src);
     if len ≠ len2 then return (Err ShapeMismatch) else do {
       let dd = i_data dest;
       let ds = i_data src;
       let loop = (λi. do {
          v1 ← Array.nth dd i;
          v2 ← Array.nth ds i;
          Array.upd i (f32_div v1 v2) dd;
          return ()
