       mapM loop [0..<len];
       return (Ok ())
     }
  } | _ ⇒ return (Err ShapeMismatch)
}"

definition tensor_clip_inplace :: "tensor_impl ⇒ f32 ⇒ f32 ⇒ (unit, err) result heap" where
"tensor_clip_inplace t mn mx = do {
  chk ← assert2DAndLen t;
  case chk of Err e ⇒ return (Err e) | Ok _ ⇒ do {
    len ← Array.len (i_data t);
    let d = i_data t;
    let loop = (λi. do {
       v ← Array.nth d i;
       Array.upd i (f32_clip mn mx v) d;
       return ()
    });
    mapM loop [0..<len];
    return (Ok ())
  }
}"

definition tensor_exp_inplace :: "tensor_impl ⇒ (unit, err) result heap" where
"tensor_exp_inplace t = do {
  chk ← assert2DAndLen t;
  case chk of Err e ⇒ return (Err e) | Ok _ ⇒ do {
    len ← Array.len (i_data t);
    let d = i_data t;
    let loop = (λi. do {
       v ← Array.nth d i;
       Array.upd i (f32_exp v) d;
       return ()
    });
    mapM loop [0..<len];
    return (Ok ())
  }
}"

definition tensor_copy :: "tensor_impl ⇒ (tensor_impl, err) result heap" where
"tensor_copy t = do {
  chk ← assert2DAndLen t;
  case chk of Err e ⇒ return (Err e) | Ok _ ⇒ do {
    len ← Array.len (i_data t);
    new_arr ← Array.new len f32_zero;
    let old_arr = i_data t;
    let loop = (λi. do {
       v ← Array.nth old_arr i;
       Array.upd i v new_arr;
       return ()
    });
    mapM loop [0..<len];
    return (Ok ⦇ i_dims = i_dims t, i_data = new_arr ⦈)
  }
}"

definition tensor_deinit :: "tensor_impl ⇒ unit heap" where
"tensor_deinit t = return ()" (* GC handles it in HOL, but models Zig deinit *)

record rsf_layer =
  s_weight :: tensor_impl
  t_weight :: tensor_impl
  s_bias :: tensor_impl
  t_bias :: tensor_impl
  s_weight_grad :: tensor_impl
  t_weight_grad :: tensor_impl
  s_bias_grad :: tensor_impl
  t_bias_grad :: tensor_impl
  dim :: nat
  clip_min :: f32
  clip_max :: f32
  grad_mean :: bool

definition rsf_layer_forward :: "rsf_layer ⇒ tensor_impl ⇒ tensor_impl ⇒ (unit, err) result heap" where
"rsf_layer_forward self x1 x2 = do {
  bs_res ← assertPair (dim self) (clip_min self) (clip_max self) (s_bias self) (t_bias self) x1 x2;
  case bs_res of Err e ⇒ return (Err e) | Ok batch_size ⇒ do {

    x2_t_res ← tensor_transpose x2;
    case x2_t_res of Err e ⇒ return (Err e) | Ok x2_t ⇒ do {
      s_x2_t_res ← tensor_matmul (s_weight self) x2_t;
      case s_x2_t_res of Err e ⇒ return (Err e) | Ok s_x2_t ⇒ do {
        s_x2_res ← tensor_transpose s_x2_t;
        case s_x2_res of Err e ⇒ return (Err e) | Ok s_x2 ⇒ do {

          let loop_b = (λb. do {
             let loop_d = (λd. do {
                bias_val ← Array.nth (i_data (s_bias self)) d;
                val ← Array.nth (i_data s_x2) (b * (dim self) + d);
                Array.upd (b * (dim self) + d) (f32_add val bias_val) (i_data s_x2);
                return ()
             });
             mapM loop_d [0..<dim self];
             return ()
          });
          mapM loop_b [0..<batch_size];

          clampFiniteInPlace s_x2;
          tensor_clip_inplace s_x2 (clip_min self) (clip_max self);
          clampFiniteInPlace s_x2;
          tensor_exp_inplace s_x2;
          clampFiniteInPlace s_x2;

          tensor_mul_inplace x1 s_x2;

          x1_t_res ← tensor_transpose x1;
          case x1_t_res of Err e ⇒ return (Err e) | Ok x1_t ⇒ do {
             t_x1_t_res ← tensor_matmul (t_weight self) x1_t;
             case t_x1_t_res of Err e ⇒ return (Err e) | Ok t_x1_t ⇒ do {
                t_x1_res ← tensor_transpose t_x1_t;
                case t_x1_res of Err e ⇒ return (Err e) | Ok t_x1 ⇒ do {

                   let loop_b2 = (λb. do {
                      let loop_d2 = (λd. do {
                         bias_val ← Array.nth (i_data (t_bias self)) d;
                         val ← Array.nth (i_data t_x1) (b * (dim self) + d);
                         Array.upd (b * (dim self) + d) (f32_add val bias_val) (i_data t_x1);
                         return ()
                      });
                      mapM loop_d2 [0..<dim self];
                      return ()
                   });
                   mapM loop_b2 [0..<batch_size];

                   clampFiniteInPlace t_x1;
                   tensor_add_inplace x2 t_x1;
                   clampFiniteInPlace x2;

                   return (Ok ())
                }
             }
          }
        }
      }
    }
  }
}"

record rsf_config =
  cfg_clip_min :: f32
  cfg_clip_max :: f32
  cfg_grad_mean :: bool
  cfg_max_dim :: nat
  cfg_max_layers :: nat

record control_block =
  freed :: "bool ref"
  cb_dim :: nat
  cb_num_layers :: nat
  cb_layers :: "rsf_layer array"
  cb_cfg :: rsf_config

record rsf =
  ctrl :: "control_block ref"

definition rsf_split :: "rsf ⇒ tensor_impl ⇒ tensor_impl ⇒ tensor_impl ⇒ (nat, err) result heap" where
"rsf_split self x x1 x2 = do {
  c ← Ref.lookup (ctrl self);
  let d = cb_dim c;
  chk ← assert2DAndLen x;
  case chk of Err e ⇒ return (Err e) | Ok _ ⇒ do {
     if i_dims x ! 1 ≠ d * 2 then return (Err ShapeMismatch) else do {
       let batch = i_dims x ! 0;
       chk1 ← assert2DAndLen x1;
       chk2 ← assert2DAndLen x2;
       case (chk1, chk2) of (Ok _, Ok _) ⇒ do {
          if i_dims x1 ! 0 ≠ batch ∨ i_dims x2 ! 0 ≠ batch then return (Err ShapeMismatch)
          else if i_dims x1 ! 1 ≠ d ∨ i_dims x2 ! 1 ≠ d then return (Err ShapeMismatch)
          else do {
             let dx = i_data x; let d1 = i_data x1; let d2 = i_data x2;
             let loop = (λb. do {
                let loop_in = (λk. do {
                   v1 ← Array.nth dx (b * d * 2 + k);
                   v2 ← Array.nth dx (b * d * 2 + d + k);
                   Array.upd (b * d + k) v1 d1;
                   Array.upd (b * d + k) v2 d2;
                   return ()
                });
                mapM loop_in [0..<d];
                return ()
             });
             mapM loop [0..<batch];
             return (Ok batch)
          }
       } | _ ⇒ return (Err ShapeMismatch)
     }
  }
}"

definition rsf_merge :: "rsf ⇒ tensor_impl ⇒ tensor_impl ⇒ tensor_impl ⇒ (unit, err) result heap" where
"rsf_merge self x1 x2 out = do {
  c ← Ref.lookup (ctrl self);
  let d = cb_dim c;
  chk ← assert2DAndLen out;
  chk1 ← assert2DAndLen x1;
  chk2 ← assert2DAndLen x2;
  case (chk, chk1, chk2) of (Ok _, Ok _, Ok _) ⇒ do {
     let batch = i_dims x1 ! 0;
     if i_dims x2 ! 0 ≠ batch ∨ i_dims out ! 0 ≠ batch then return (Err ShapeMismatch)
     else if i_dims x1 ! 1 ≠ d ∨ i_dims x2 ! 1 ≠ d ∨ i_dims out ! 1 ≠ d * 2 then return (Err ShapeMismatch)
     else do {
        let d1 = i_data x1; let d2 = i_data x2; let dout = i_data out;
        let loop = (λb. do {
           let loop_in = (λk. do {
              v1 ← Array.nth d1 (b * d + k);
              v2 ← Array.nth d2 (b * d + k);
              Array.upd (b * d * 2 + k) v1 dout;
              Array.upd (b * d * 2 + d + k) v2 dout;
              return ()
           });
           mapM loop_in [0..<d];
           return ()
        });
        mapM loop [0..<batch];
        return (Ok ())
     }
  } | _ ⇒ return (Err ShapeMismatch)
}"

definition rsf_forward :: "rsf ⇒ tensor_impl ⇒ (unit, err) result heap" where
"rsf_forward self x = do {
  c ← Ref.lookup (ctrl self);
  fr ← Ref.lookup (freed c);
  if fr then return (Err NotInitialized) else do {
     chk ← assert2DAndLen x;
     case chk of Err e ⇒ return (Err e) | Ok _ ⇒ do {
        let d = cb_dim c;
        if i_dims x ! 1 ≠ d * 2 then return (Err ShapeMismatch) else do {
           let batch = i_dims x ! 0;
           arr1 ← Array.new (batch * d) f32_zero;
           arr2 ← Array.new (batch * d) f32_zero;
           let x1 = ⦇ i_dims = [batch, d], i_data = arr1 ⦈;
           let x2 = ⦇ i_dims = [batch, d], i_data = arr2 ⦈;

           split_res ← rsf_split self x x1 x2;
           case split_res of Err e ⇒ return (Err e) | Ok _ ⇒ do {
              let layers = cb_layers c;
              let num = cb_num_layers c;
              let loop = (λi. do {
                 l ← Array.nth layers i;
                 rsf_layer_forward l x1 x2
              });

              res ← foldM (λ_ i. do {
                 r ← loop i;
                 case r of Ok _ ⇒ return (Ok ()) | Err e ⇒ return (Err e)
              }) (Ok ()) [0..<num];

              case res of Err e ⇒ return (Err e) | Ok _ ⇒ rsf_merge self x1 x2 x
           }
        }
     }
  }
}"

