section ‹Imperative Layer›

record tensor_impl =
  i_dims :: "nat list"
  i_data :: "f32 array"

definition tensor_valid :: "tensor_impl ⇒ bool heap" where
"tensor_valid t = do {
  len ← Array.len (i_data t);
  return (length (i_dims t) = 2 ∧ len = (i_dims t ! 0) * (i_dims t ! 1))
}"

definition assert2DAndLen :: "tensor_impl ⇒ (unit, err) result heap" where
"assert2DAndLen t = do {
  len ← Array.len (i_data t);
  if length (i_dims t) ≠ 2 then return (Err ShapeMismatch)
  else if len ≠ (i_dims t ! 0) * (i_dims t ! 1) then return (Err DataLengthMismatch)
  else return (Ok ())
}"

definition assertPair :: "nat ⇒ f32 ⇒ f32 ⇒ tensor_impl ⇒ tensor_impl ⇒ tensor_impl ⇒ tensor_impl ⇒ (nat, err) result heap" where
"assertPair dim cmin cmax sb tb a b = do {
  ra ← assert2DAndLen a;
  rb ← assert2DAndLen b;
  case (ra, rb) of
    (Ok _, Ok _) ⇒ do {
       if i_dims a ! 1 ≠ dim ∨ i_dims b ! 1 ≠ dim then return (Err ShapeMismatch)
       else if i_dims a ! 0 ≠ i_dims b ! 0 then return (Err ShapeMismatch)
       else do {
         len_sb ← Array.len (i_data sb);
         len_tb ← Array.len (i_data tb);
         if len_sb ≠ dim ∨ len_tb ≠ dim then return (Err ShapeMismatch)
         else if ¬ is_finite cmin ∨ ¬ is_finite cmax then return (Err NonFinite)
         else if ¬ f32_lt cmin cmax then return (Err InvalidConfig)
         else return (Ok (i_dims a ! 0))
       }
    }
  | (Err e, _) ⇒ return (Err e)
  | (_, Err e) ⇒ return (Err e)
}"

definition clampFiniteInPlace :: "tensor_impl ⇒ unit heap" where
"clampFiniteInPlace t = do {
  len ← Array.len (i_data t);
  let d = i_data t;
  let loop = (λi. do {
      v ← Array.nth d i;
      if ¬ is_finite v then Array.upd i f32_zero d else return ();
      return ()
  });
  mapM loop [0..<len];
  return ()
}"

definition tensor_transpose :: "tensor_impl ⇒ (tensor_impl, err) result heap" where
"tensor_transpose t = do {
  chk ← assert2DAndLen t;
  case chk of Err e ⇒ return (Err e) | Ok _ ⇒ do {
    let r = i_dims t ! 0;
    let c = i_dims t ! 1;
    new_arr ← Array.new (r*c) f32_zero;
    let old_arr = i_data t;
    let loop = (λi. do {
       let loop_inner = (λj. do {
          val ← Array.nth old_arr (i * c + j);
          Array.upd (j * r + i) val new_arr;
          return ()
       });
       mapM loop_inner [0..<c];
       return ()
    });
    mapM loop [0..<r];
    return (Ok ⦇ i_dims = [c, r], i_data = new_arr ⦈)
  }
}"

definition tensor_matmul :: "tensor_impl ⇒ tensor_impl ⇒ (tensor_impl, err) result heap" where
"tensor_matmul a b = do {
  ca ← assert2DAndLen a;
  cb ← assert2DAndLen b;
  case (ca, cb) of (Ok _, Ok _) ⇒ do {
    let m = i_dims a ! 0;
    let k = i_dims a ! 1;
    let k' = i_dims b ! 0;
    let n = i_dims b ! 1;
    if k ≠ k' then return (Err ShapeMismatch) else do {
      res ← Array.new (m*n) f32_zero;
      let da = i_data a;
      let db = i_data b;
      let loop_i = (λi. do {
        let loop_j = (λj. do {
           let loop_k = (λl acc. do {
              v1 ← Array.nth da (i * k + l);
              v2 ← Array.nth db (l * n + j);
              return (f32_add acc (f32_mul v1 v2))
           });
           sum ← foldM loop_k f32_zero [0..<k];
           Array.upd (i * n + j) sum res;
           return ()
        });
        mapM loop_j [0..<n];
        return ()
      });
      mapM loop_i [0..<m];
      return (Ok ⦇ i_dims = [m, n], i_data = res ⦈)
    }
  } | (Err e, _) ⇒ return (Err e) | (_, Err e) ⇒ return (Err e)
}"

definition tensor_add_inplace :: "tensor_impl ⇒ tensor_impl ⇒ (unit, err) result heap" where
"tensor_add_inplace dest src = do {
  cd ← assert2DAndLen dest;
  cs ← assert2DAndLen src;
  case (cd, cs) of (Ok _, Ok _) ⇒ do {
