definition tensor_deinit :: "tensor_impl ⇒ unit heap" where
"tensor_deinit t = return ()" (* GC handles it in HOL, but models Zig deinit *)

record rsf_layer =
  s_weight :: tensor_impl
  t_weight :: tensor_impl
  s_bias :: tensor_impl
  t_bias :: tensor_impl
  s_weight_grad :: tensor_impl
  t_weight_grad :: tensor_impl
  s_bias_grad :: tensor_impl
  t_bias_grad :: tensor_impl
  dim :: nat
  clip_min :: f32
  clip_max :: f32
  grad_mean :: bool

definition rsf_layer_forward :: "rsf_layer ⇒ tensor_impl ⇒ tensor_impl ⇒ (unit, err) result heap" where
"rsf_layer_forward self x1 x2 = do {
  bs_res ← assertPair (dim self) (clip_min self) (clip_max self) (s_bias self) (t_bias self) x1 x2;
  case bs_res of Err e ⇒ return (Err e) | Ok batch_size ⇒ do {

    x2_t_res ← tensor_transpose x2;
    case x2_t_res of Err e ⇒ return (Err e) | Ok x2_t ⇒ do {
      s_x2_t_res ← tensor_matmul (s_weight self) x2_t;
      case s_x2_t_res of Err e ⇒ return (Err e) | Ok s_x2_t ⇒ do {
        s_x2_res ← tensor_transpose s_x2_t;
        case s_x2_res of Err e ⇒ return (Err e) | Ok s_x2 ⇒ do {

          let loop_b = (λb. do {
             let loop_d = (λd. do {
                bias_val ← Array.nth (i_data (s_bias self)) d;
                val ← Array.nth (i_data s_x2) (b * (dim self) + d);
                Array.upd (b * (dim self) + d) (f32_add val bias_val) (i_data s_x2);
                return ()
             });
             mapM loop_d [0..<dim self];
             return ()
          });
          mapM loop_b [0..<batch_size];

          clampFiniteInPlace s_x2;
          tensor_clip_inplace s_x2 (clip_min self) (clip_max self);
          clampFiniteInPlace s_x2;
          tensor_exp_inplace s_x2;
          clampFiniteInPlace s_x2;

          tensor_mul_inplace x1 s_x2;

          x1_t_res ← tensor_transpose x1;
          case x1_t_res of Err e ⇒ return (Err e) | Ok x1_t ⇒ do {
             t_x1_t_res ← tensor_matmul (t_weight self) x1_t;
             case t_x1_t_res of Err e ⇒ return (Err e) | Ok t_x1_t ⇒ do {
                t_x1_res ← tensor_transpose t_x1_t;
                case t_x1_res of Err e ⇒ return (Err e) | Ok t_x1 ⇒ do {

                   let loop_b2 = (λb. do {
                      let loop_d2 = (λd. do {
                         bias_val ← Array.nth (i_data (t_bias self)) d;
                         val ← Array.nth (i_data t_x1) (b * (dim self) + d);
                         Array.upd (b * (dim self) + d) (f32_add val bias_val) (i_data t_x1);
                         return ()
                      });
                      mapM loop_d2 [0..<dim self];
                      return ()
                   });
                   mapM loop_b2 [0..<batch_size];

                   clampFiniteInPlace t_x1;
                   tensor_add_inplace x2 t_x1;
                   clampFiniteInPlace x2;

                   return (Ok ())
                }
             }
          }
        }
      }
    }
  }
}"

