definition rsf_split :: "rsf ⇒ tensor_impl ⇒ tensor_impl ⇒ tensor_impl ⇒ (nat, err) result heap" where
"rsf_split self x x1 x2 = do {
  c ← Ref.lookup (ctrl self);
  let d = cb_dim c;
  chk ← assert2DAndLen x;
  case chk of Err e ⇒ return (Err e) | Ok _ ⇒ do {
     if i_dims x ! 1 ≠ d * 2 then return (Err ShapeMismatch) else do {
       let batch = i_dims x ! 0;
       chk1 ← assert2DAndLen x1;
       chk2 ← assert2DAndLen x2;
       case (chk1, chk2) of (Ok _, Ok _) ⇒ do {
          if i_dims x1 ! 0 ≠ batch ∨ i_dims x2 ! 0 ≠ batch then return (Err ShapeMismatch)
          else if i_dims x1 ! 1 ≠ d ∨ i_dims x2 ! 1 ≠ d then return (Err ShapeMismatch)
          else do {
             let dx = i_data x; let d1 = i_data x1; let d2 = i_data x2;
             let loop = (λb. do {
                let loop_in = (λk. do {
                   v1 ← Array.nth dx (b * d * 2 + k);
                   v2 ← Array.nth dx (b * d * 2 + d + k);
                   Array.upd (b * d + k) v1 d1;
                   Array.upd (b * d + k) v2 d2;
                   return ()
                });
                mapM loop_in [0..<d];
                return ()
             });
             mapM loop [0..<batch];
             return (Ok batch)
          }
       } | _ ⇒ return (Err ShapeMismatch)
     }
  }
}"

definition rsf_merge :: "rsf ⇒ tensor_impl ⇒ tensor_impl ⇒ tensor_impl ⇒ (unit, err) result heap" where
"rsf_merge self x1 x2 out = do {
  c ← Ref.lookup (ctrl self);
  let d = cb_dim c;
  chk ← assert2DAndLen out;
  chk1 ← assert2DAndLen x1;
  chk2 ← assert2DAndLen x2;
  case (chk, chk1, chk2) of (Ok _, Ok _, Ok _) ⇒ do {
     let batch = i_dims x1 ! 0;
     if i_dims x2 ! 0 ≠ batch ∨ i_dims out ! 0 ≠ batch then return (Err ShapeMismatch)
     else if i_dims x1 ! 1 ≠ d ∨ i_dims x2 ! 1 ≠ d ∨ i_dims out ! 1 ≠ d * 2 then return (Err ShapeMismatch)
     else do {
        let d1 = i_data x1; let d2 = i_data x2; let dout = i_data out;
        let loop = (λb. do {
           let loop_in = (λk. do {
              v1 ← Array.nth d1 (b * d + k);
              v2 ← Array.nth d2 (b * d + k);
              Array.upd (b * d * 2 + k) v1 dout;
              Array.upd (b * d * 2 + d + k) v2 dout;
              return ()
           });
           mapM loop_in [0..<d];
           return ()
        });
        mapM loop [0..<batch];
        return (Ok ())
     }
  } | _ ⇒ return (Err ShapeMismatch)
}"

definition rsf_forward :: "rsf ⇒ tensor_impl ⇒ (unit, err) result heap" where
"rsf_forward self x = do {
  c ← Ref.lookup (ctrl self);
  fr ← Ref.lookup (freed c);
  if fr then return (Err NotInitialized) else do {
     chk ← assert2DAndLen x;
     case chk of Err e ⇒ return (Err e) | Ok _ ⇒ do {
        let d = cb_dim c;
        if i_dims x ! 1 ≠ d * 2 then return (Err ShapeMismatch) else do {
           let batch = i_dims x ! 0;
           arr1 ← Array.new (batch * d) f32_zero;
           arr2 ← Array.new (batch * d) f32_zero;
           let x1 = ⦇ i_dims = [batch, d], i_data = arr1 ⦈;
           let x2 = ⦇ i_dims = [batch, d], i_data = arr2 ⦈;

           split_res ← rsf_split self x x1 x2;
           case split_res of Err e ⇒ return (Err e) | Ok _ ⇒ do {
              let layers = cb_layers c;
              let num = cb_num_layers c;
              let loop = (λi. do {
                 l ← Array.nth layers i;
                 rsf_layer_forward l x1 x2
              });

              res ← foldM (λ_ i. do {
                 r ← loop i;
                 case r of Ok _ ⇒ return (Ok ()) | Err e ⇒ return (Err e)
              }) (Ok ()) [0..<num];

              case res of Err e ⇒ return (Err e) | Ok _ ⇒ rsf_merge self x1 x2 x
           }
        }
     }
  }
}"

